        out=bytes([0x20|(1 if sflag else 0), mt])+length.to_bytes(2,'big')
        if sflag: out+=seid.to_bytes(8,'big')
        out+=seq.to_bytes(3,'big')+bytes([0])
        return out+body
    return prefix+body

def run_batch(cands):
    p=subprocess.Popen([BIN,'-config',CFG],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    time.sleep(0.6)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
    s.connect(ADDR)
    s.settimeout(0.05)
    for idx,c in enumerate(cands):
        try:
            s.send(c)
        except OSError:
            pass
        time.sleep(0.03)
        rc=p.poll()
        if rc is not None:
            # crash/exit
            try:s.send(b'') 
            except:pass
            try:p.wait(3)
            except:p.kill();p.wait()
            out=p.stdout.read().decode('latin1'); err=p.stderr.read().decode('latin1')
